import Ajv from 'ajv';
import type {ValidateFunction, ErrorObject} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema, returning a rejection ToolResponse on schema failure and throwing only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.getValidator(tool, definition);
    if (!validator(input)) {
      const error = this.formatValidationErrors(validator.errors);
      log.warn('tool', 'validation failed', {name, error});
      return {result: error};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getValidator(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) {
      return tool.validator;
    }
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) {
      return cached;
    }
    try {
      const validator = this.ajv.compile(definition.inputSchema);
      this.dynamicValidators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Failed to compile inputSchema for tool "${definition.name}": ${message}`);
    }
  }

  private formatValidationErrors(errors: ErrorObject[] | null | undefined): string {
    if (!errors || errors.length === 0) {
      return 'Invalid input';
    }
    return errors
      .map(err => {
        const propPath = err.dataPath ? err.dataPath.replace(/^\./, '') : '';
        if (err.keyword === 'required') {
          const missing = (err.params as {missingProperty?: string}).missingProperty ?? '';
          const field = propPath ? `${propPath}.${missing}` : missing;
          return `Missing required property "${field}".`;
        }
        if (err.keyword === 'type') {
          const expected = (err.params as {type?: string}).type ?? 'unknown';
          return `Property "${propPath}" must be of type ${expected}.`;
        }
        if (err.keyword === 'enum') {
          const allowed = (err.params as {allowedValues?: unknown[]}).allowedValues;
          const allowedStr = Array.isArray(allowed) ? allowed.join(', ') : String(allowed);
          return `Property "${propPath}" must be one of: ${allowedStr}.`;
        }
        return propPath ? `Property "${propPath}" ${err.message}.` : (err.message ?? 'Invalid input');
      })
      .join(' ');
  }
}

